        if zigzag(T[i]):
            print(T[i], end=' ')


def zigzag(ch):
    i = -1
    c = 1
    ok = True
    test_croissance = ch[0] < ch[1]
    if test_croissance:
        while ok and i < len(ch) - 2:
            i += 1
            a = ord(ch[i]) * c
            b = ord(ch[i + 1]) * c
            ok = a < b
            c *= -1
    elif not (test_croissance):
        while ok and i < len(ch) - 2:
            i += 1
            a = ord(ch[i]) * c
            b = ord(ch[i + 1]) * c
            ok = a > b
            c *= -1
    else:
        ok = False
    return ok


